(function(w){
  function close(value){const c=document.querySelector('.swal2-container');if(c)c.remove();return value}
  function fire(opts){if(typeof opts==='string')opts={title:opts};opts=opts||{};return new Promise(resolve=>{const old=document.querySelector('.swal2-container');if(old)old.remove();const c=document.createElement('div');c.className='swal2-container';c.setAttribute('role','dialog');c.setAttribute('aria-modal','true');const p=document.createElement('div');p.className='swal2-popup';const type=opts.icon||'info';const i=document.createElement('div');i.className='swal2-icon '+type;i.textContent=type==='success'?'✓':type==='error'?'×':type==='warning'?'!':'i';const t=document.createElement('h2');t.className='swal2-title';t.textContent=opts.title||'Confirm action';const h=document.createElement('div');h.className='swal2-html-container';h.textContent=opts.text||'';const a=document.createElement('div');a.className='swal2-actions';const confirm=document.createElement('button');confirm.type='button';confirm.className='swal2-confirm';confirm.textContent=opts.confirmButtonText||'OK';a.appendChild(confirm);let cancel=null;if(opts.showCancelButton){cancel=document.createElement('button');cancel.type='button';cancel.className='swal2-cancel';cancel.textContent=opts.cancelButtonText||'Cancel';a.appendChild(cancel)}p.append(i,t,h,a);c.appendChild(p);document.body.appendChild(c);confirm.focus();const done=(confirmed)=>{c.remove();resolve({isConfirmed:confirmed,isDismissed:!confirmed})};confirm.addEventListener('click',()=>done(true));cancel?.addEventListener('click',()=>done(false));c.addEventListener('click',e=>{if(e.target===c&&opts.allowOutsideClick!==false)done(false)});const key=e=>{if(e.key==='Escape'){document.removeEventListener('keydown',key);done(false)}};document.addEventListener('keydown',key,{once:true})})}
  w.Swal={fire};
})(window);
